  _areaFilterSettingHtml(){const scopes=(this._boot.areas||[]).map(area=>({id:area.id,name:this._areaName(area)}));const hidden=new Set(this._boot.config.hidden_entities||[]);return `<section class="panel settingsPanel"><h2>${this._t('deviceFilters')}</h2><p class="sectionIntro">${this._t('filtersHelp')}</p><div class="areaFilterList">${scopes.map(scope=>{const entries=this._scopeRegistryEntries(scope.id);return `<details class="areaFilter"><summary><b>${esc(scope.name)}</b><span>${entries.length} ${this._t('entities')}</span></summary><div class="areaFilterBody"><div class="domainChoices">${this._orderedCategories().map(category=>`<label class="domainChoice"><input type="checkbox" data-filter-scope="${esc(scope.id)}" data-filter-domain="${category}" ${this._areaDomainAllowed(scope.id,category)?'checked':''}> ${ICONS[category]} ${esc(this._domainLabel(category))}</label>`).join('')}</div><input class="filterSearch" data-entity-search="${esc(scope.id)}" placeholder="${esc(this._t('searchEntity'))}"><div class="entityChoices">${entries.map(state=>{const category=this._displayCategory(state);return `<label class="entityChoice" data-entity-choice="${esc(scope.id)}"><input type="checkbox" data-entity-visible="${esc(state.entity_id)}" ${hidden.has(state.entity_id)?'':'checked'}> <span>${ICONS[category]} ${esc(this._name(state))}</span></label>`}).join('')||`<span class="backgroundSource">${this._t('entities')}: 0</span>`}</div></div></details>`}).join('')}</div><button class="save" id="saveAreaFilters" style="margin-top:15px">${this._t('save')}</button></section>`}
  _mediaPickerHtml(){const picker=this._mediaPicker,items=picker.items||[];return `<div class="drawer"><section class="sheet" role="dialog" aria-modal="true"><div class="sheetHead"><div><small>Home Assistant Media</small><h2>${esc(picker.title||"Media")}</h2></div><button class="close" data-media-close>${this._t("close")}</button></div><div class="mediaPath">${picker.history?.length?`<button data-media-back>← Back</button>`:""}<span>${picker.loading?'Loading…':`${items.length} items`}</span></div>${picker.error?`<div class="empty">${esc(picker.error)}</div>`:`<div class="mediaGrid">${items.map((item,index)=>`<button class="mediaItem" data-media-index="${index}"><div class="mediaThumb" ${item.thumbnail?`style="background-image:url('${esc(item.thumbnail)}')"`:""}>${item.thumbnail?'':item.can_expand?'▣':'▧'}</div><span>${esc(item.title)}</span></button>`).join("")||`<div class="empty">No image media found</div>`}</div>`}</section></div>`}
  _navHtml(){const items=[["home","home",this._t("home")],["floors","floors",this._t("floors")],["areas","areas",this._t("areas")]];if(this._cameraEntities().length)items.push(["cameras","camera",this._t("cameraCenter")]);return items.map(([view,icon,name])=>`<button class="navBtn ${this._view===view?'active':''}" data-view="${view}"><span>${iconHtml(icon)}</span><b>${esc(name)}</b></button>`).join("")+(this._boot.user.is_admin?`<button class="navBtn ${this._view==='settings'?'active':''}" data-view="settings"><span>${iconHtml('settings')}</span><b>${this._t("settings")}</b></button>`:"")}
