  _activityOverviewHtml(all){const cfg=this._homeLayoutConfig();if(!cfg.show_activity_overview)return "";const categories=cfg.activity_categories.filter(category=>this._availableCategories(all).includes(category)),scale=Math.max(.8,Math.min(1.35,Number(cfg.activity_scale)||1));return `<aside class="clyStatus" style="--activity-scale:${scale}"><div class="clyStatusHead"><div><h2>${this._t('activityOverview')}</h2><small>${this._t('jumpToDevices')}</small></div><span class="live">${this._t('live')}</span></div>${categories.map(category=>{const count=all.filter(state=>this._displayCategory(state)===category&&isOn(state.state)).length;return `<button class="clyMetric" data-rail-filter="${category}" ${count?'':'disabled'}>${ICONS[category]}<span>${esc(this._domainLabel(category))}<small>${this._t(count?'active':'inactive')}</small></span><b>${count}</b></button>`}).join('')}</aside>`;}
